{
  "status": "INSUFFICIENT_EVIDENCE",
  "core_findings": [
    {
      "finding": "Reported sampler and serving checks pass in all four categories; these checks reveal no serving defect within their tested coverage.",
      "evidence": "Each category reports sampler_contract.passed=true, valid_batches=10/10, invalid_batches=0 and reserved_tokens_valid=true. Supervised-position counts are Movies_and_TV=2242, Industrial_and_Scientific=2250, Electronics=2179 and CDs_and_Vinyl=2709. Each serving_parity reports available=true, passed=true, cases=67, ordered_ranking_agreement=1.0 and top10_agreement=1.0. Maximum absolute score errors are respectively 3.8147e-6, 1.9073e-6, 1.9073e-6 and 3.8147e-6, under atol=1e-5/rtol=1e-4. External-label mutation remains untested."
    },
    {
      "finding": "Training-prefix predictions show measured history sensitivity, especially to recent-item deletion; evidence for an effect of swapping the last two items on target rank is inconclusive.",
      "evidence": "history_sensitivity uses 64 users/category and fixed target-plus-99-negative candidate sets. recent_deleted.target_score_delta means [95% intervals] are Movies_and_TV=-1.2962 [-1.6423,-0.9424], Industrial_and_Scientific=-0.2524 [-0.4072,-0.1038], Electronics=-0.3880 [-0.5777,-0.2216], CDs_and_Vinyl=-0.4098 [-0.6320,-0.1950]. Corresponding diagnostic_hit10_delta values are 0 [0,0], -0.0625 [-0.15625,0.015625], -0.078125 [-0.171875,0] and -0.03125 [-0.078125,0]. last_two_swapped.target_rank_delta intervals all include zero: Movies [-0.046875,0.171875], Industrial [-0.84453125,0.430078125], Electronics [-0.4375,0.383203125], CDs [-0.125,0.015625]. Every single-category report has four_category_macro=null and four_category_macro_available=false; no aggregated macro uncertainty is supplied."
    },
    {
      "finding": "Residual patching provides conditional exploratory effects, but no four-category corrected discovery or demonstrated repair.",
      "evidence": "residual_patching.available=true in every category. Exploration has 32 users/category; disjoint confirmation has 32/category. Reported attempted sites are input_residual and enter_second_attention, using matched_donor_A/B in restore/disrupt directions. For example, exploration/matched_donor_A/restore/input_residual.hit10 is Movies=0.21875 [0.09375,0.375], Industrial=0.28125 [0.125,0.46875], Electronics=0.15625 [0,0.3125], CDs=0.0625 [0,0.15625]. These are intervention-minus-destination effects, not improvements over ordinary serving. Listed confirmation raw_p values range from 0.0250512 to 0.701693; holm_adjusted_p=null throughout the displayed confirmations. The complete cross-category testing family is not provided."
    }
  ],
  "key_implications": [
    {
      "implication": "Any change emphasizing recent context remains a hypothesis requiring independent host validation within the single BERT4Rec model per category.",
      "evidence": "Recent deletion lowers mean target scores in all four categories, but diagnostic_hit10_delta intervals all include zero. These are training-prefix candidate results, not host validation HR@10. Intervals describe sampled-user uncertainty only, excluding training-seed and candidate-sampling uncertainty; repeated validation selection is optimistic. No score fusion or additional predictor is justified."
    },
    {
      "implication": "Embedding alignment and sampled training separation cannot establish capacity, recommendation quality, or convergence.",
      "evidence": "embedding_collapse_score, with embedding_sample_count=2048/category, is Movies=0.644085, Industrial=0.802252, Electronics=0.796711 and CDs=0.676859. This is mapped mean cosine; 0.5 means approximately zero mean cosine. pos_neg_margin_mean is respectively 9.62786, 3.98711, 3.89876 and 7.72223; pos_neg_neg_beats_pos_rate is 0.0209634, 0.0777778, 0.0826067 and 0.0361757, over 2242/2250/2179/2709 in-sample positions. No uncertainty intervals are supplied for these statistics. training_trajectories.available=false in all categories, leaving convergence unassessed."
    },
    {
      "implication": "Patching interpretation is limited by omitted control details and applies only to the specified corruption and intervention.",
      "evidence": "Displayed residual summaries report controls_passed=true, but individual identity, structural-zero, MASK-restoration, unrelated-donor and norm-matched random-control outcomes are omitted. Their magnitudes and any nonzero control effects cannot be assessed. Frequency/recency matching supplies no semantic compatibility evidence, and natural activation patches can create out-of-distribution hybrid computations. No optimizer-transfer audit or trained repair is supplied."
    }
  ],
  "evidence": {
    "residual_protocol_and_completion": {
      "seconds_cap_per_category": 30.0,
      "maximum_users_per_category": 64,
      "minimum_users_per_partition": 8,
      "completed_interventions_per_category": 384,
      "completed_forwards_per_category": 2048,
      "completed_users_by_partition_per_category": {"exploration": 32, "confirmation": 32},
      "reported_attempted_sites": ["input_residual", "enter_second_attention"],
      "coverage_limit": "Records and summaries contain omitted entries; exhaustive attempted-site coverage cannot be verified.",
      "patch_specific_elapsed_seconds": null,
      "elapsed_diagnostic_seconds": {"Movies_and_TV": 7.215606, "Industrial_and_Scientific": 7.881813, "Electronics": 8.079121, "CDs_and_Vinyl": 8.410821},
      "elapsed_definition": "These are total diagnostic wall times, including loading, probes and bootstrap, not isolated patch timings.",
      "missing_donors": null,
      "missing_donors_definition": "Missing unrelated donors block confirmation by protocol; actual donor-availability counts are omitted and cannot be assumed zero.",
      "control_results": "All displayed effects summaries have controls_passed=true. Detailed control outcomes are unavailable in this excerpt; neither zero unrelated/random effects nor their absence is established.",
      "multiplicity": "No four-category Holm-adjusted result is available. A protocol-described 16*p bound is conservative Bonferroni, not Holm; numerical bounds are omitted."
    },
    "unavailable_information": "Host validation metrics, complete paired outcomes, training trajectories, item-category breakdowns, ratings, review text, prices, stores and simulator traits are unavailable. Null denotes unavailable. No quality gain, latent intent or user trait is established by these diagnostics."
  }
}
